using System;using System.IO;using System.Linq;using Musikbox;
class Gain57Tests {static void Main(string[] args){string root=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);var song=MediaMetadata.Read(Path.GetFullPath(args[0]));string exe=Path.GetFullPath(args[2]);string log=BatchGain.Analyze(new[]{song},exe,()=>{});if(!log.Contains("input.mp3"))throw new Exception("Track-Analyse fehlt");Console.WriteLine("PASS Trackanalyse");log=BatchGain.AnalyzeAlbums(new[]{song},exe,()=>{});if(!log.Contains("0000.mp3"))throw new Exception("Albumanalyse fehlt");Console.WriteLine("PASS Albumanalyse");foreach(string mode in new[]{"Track","Album"}){string output=BatchGain.WriteCopies(new[]{song},exe,root,mode,89,()=>{});var file=Directory.GetFiles(output,"*.mp3").Single();var updated=MediaMetadata.Read(file);if(updated.Duration<2.9)throw new Exception("Ungültiges Gain-Ergebnis");Console.WriteLine("PASS "+mode+" Gain");var adjusted=MediaMetadata.Read(file);string undo=BatchGain.WriteCopies(new[]{adjusted},exe,root,"Undo",89,()=>{});if(Directory.GetFiles(undo,"*.mp3").Length!=1)throw new Exception("Undo fehlt");Console.WriteLine("PASS Gain-Rücknahme "+mode);}Console.WriteLine("BESTANDEN 6 echte MP3Gain-Prüfungen (Linux-Engine)");}}
